const $=id=>document.getElementById(id), C=id=>CARDS.find(c=>c.id===id), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let V=null,session=null,busy=false,inFlight=null,actionWaiting=false,timer,toastTimer,modalRevision=-1,lastRoll=0,lastEvent=0,fxTimer;
try{session=JSON.parse(localStorage.getItem('hts-online-v04'))}catch{}
const notice=t=>{$('status').textContent=t;$('toast').textContent=t;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,3200)};
function modal(h){$('modal').innerHTML=h;$('modal').hidden=false;document.body.classList.add('modal-open');modalRevision=V?.rev??-1}function closeM(){$('modal').hidden=true;document.body.classList.remove('modal-open')}function leave(){clearInterval(timer);V=null;lastRoll=0;lastEvent=0;closeM();$('game').hidden=true;$('onlineLobby').hidden=true;$('home').hidden=false;notice('Đã rời giao diện. Có thể kết nối lại.');}
function request(op,extra={}){if(inFlight)return Promise.resolve(false);inFlight=send(op,extra).finally(()=>{inFlight=null});return inFlight;}
async function send(op,extra={}){busy=true;try{let b={code:session?.code,token:session?.token,rev:V?.rev,op,...extra};let r=await fetch('/api/room',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(b),cache:'no-store'});let d=await r.json();if(!r.ok)throw Error(d.error||'Không kết nối được');if(d.token){session={code:b.code,token:d.token};localStorage.setItem('hts-online-v04',JSON.stringify(session))}if(d.view){let changed=V?.rev!==d.view.rev;V=d.view;if(changed){if(!$('modal').hidden&&modalRevision!==V.rev)closeM();render();if(V.pending?.type==='skillTarget'&&V.pending.actor===V.me)targetMenu()}}return true}catch(e){if(!['state','tick'].includes(op)||!V)notice(e.message);else $('log').textContent='Mất kết nối — đang thử lại';return false}finally{busy=false}}
async function action(op,extra={}){if(actionWaiting)return false;actionWaiting=true;document.body.classList.add('sending');let rev=V?.rev;try{if(inFlight)await inFlight;if(V?.rev!==rev){notice('Trạng thái đã thay đổi — hãy chọn lại thao tác');return false;}return await request(op,extra);}finally{actionWaiting=false;document.body.classList.remove('sending')}}
function poll(){clearInterval(timer);timer=setInterval(()=>{if(!document.hidden&&!actionWaiting&&!inFlight)request('tick')},1500)}
function code(){let a=new Uint8Array(8);crypto.getRandomValues(a);return [...a].map(v=>'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'[v%32]).join('')}
$('create').onclick=async()=>{if(await request('create',{code:code(),name:$('name').value}))poll()};$('join').onclick=async()=>{if(await request('join',{code:$('code').value.trim().toUpperCase(),name:$('name').value}))poll()};$('resume').onclick=async()=>{if(!session)return notice('Chưa có phiên');if(await request('state'))poll()};$('copy').onclick=async()=>{try{await navigator.clipboard.writeText(session.code);notice('Đã sao chép')}catch{notice('Mã phòng: '+session.code)}};
$('addBot').onclick=()=>action('addBot');$('solo').onclick=async()=>{if(await request('create',{code:code(),name:$('name').value})){let n=Number($('botCount').value);for(let i=0;i<n;i++){if(!await request('addBot'))break}poll()}};
$('ready').onclick=()=>action('ready');$('startOnline').onclick=()=>action('start');$('draw').onclick=()=>action('draw');$('reset').onclick=()=>modal('<h2>Đổi 5 lá?</h2><p>Tốn 3 điểm hành động.</p><button class="gold" onclick="closeM();action(\'reset\')">Đồng ý</button> <button onclick="closeM()">Đóng</button>');$('next').onclick=()=>action('next');$('effects').onclick=()=>modal('<h2>Chiến thắng đội hình</h2><p>Kiểm tra điều kiện đội hình.</p><button onclick="closeM();action(\'claim\',{checked:true})">Xác nhận thắng đội hình</button> <button onclick="closeM()">Đóng</button>');
function card(id,fn){return `<button class="card" onclick="${fn}"><img draggable="false" src="${C(id).src}" alt="${esc(C(id).type)}"></button>`}
function targetCard(t){let fn=`action('skillTarget',{player:${t.player},id:'${t.id}'})`;return t.id.startsWith('option-')||t.id.startsWith('drawcount-')?`<button class="gold" onclick="${fn}">${({'option-draw':'Rút bài','option-hero':'Anh hùng','option-monster':'Quái vật','option-challenge':'Thử thách'})[t.id]||('Rút '+t.id.slice(10)+' lá')}</button>`:t.id.startsWith('modvalue-')?`<button class="gold" onclick="${fn}">${Number(t.id.slice(9))>0?'+':''}${t.id.slice(9)}</button>`:t.id.startsWith('value-')?`<button class="gold" onclick="${fn}">${t.id==='value-plus'?'+5':'-5'}</button>`:t.id.startsWith('slot-')?`<button class="blindCard" onclick="${fn}" aria-label="Lấy lá ${Number(t.id.slice(5))+1}"><span class="back"></span><small>Lá ${Number(t.id.slice(5))+1}</small></button>`:card(t.id,fn)}
function stableHTML(id,html){let el=$(id);if(el.dataset.rendered===html)return;let x=el.scrollLeft,y=el.scrollTop;el.innerHTML=html;el.dataset.rendered=html;el.scrollLeft=x;el.scrollTop=y;}
function render(){let s=V,me=s.players[s.me],myTurn=s.turn===s.me&&s.phase==='play'&&!s.pending;$('home').hidden=true;$('onlineLobby').hidden=s.phase!=='lobby';$('game').hidden=s.phase==='lobby';if(s.phase==='lobby'){$('roomCode').textContent=session.code;$('addBot').hidden=s.me!==0||s.players.length>=6;$('lobbyMsg').textContent='Chọn thủ lĩnh rồi bấm sẵn sàng. '+s.players.length+'/6 người';$('roomPlayers').innerHTML=s.players.map((p,i)=>`<div class="tile">${esc(p.name)} ${i===0?'· Chủ phòng':p.bot?'· AI':''}${s.me===0&&p.bot?` <button onclick="action('removeBot',{index:${i}})">Xóa</button>`:''}<br>${p.ready?'✓ Sẵn sàng':'Đang chọn'}${p.leader?card(p.leader,`detail('${p.leader}','view')`):''}</div>`).join('');$('leaders').innerHTML=CARDS.filter(c=>c.type==='leader'&&!s.players.some((p,i)=>i!==s.me&&p.leader===c.id)).map(c=>card(c.id,`choose('${c.id}')`)).join('');$('ready').disabled=!me.leader;$('ready').textContent=me.ready?'Hủy sẵn sàng':'Sẵn sàng';$('startOnline').disabled=s.me!==0||s.players.length<2||!s.players.every(p=>p.ready);return}
$('turn').textContent=s.phase==='done'?'Kết thúc':s.players[s.turn].name+' · '+s.ap+' điểm';stableHTML('players',s.players.map((p,i)=>`<div class="player ${i===s.turn?'active':''}"><b>${esc(p.name)}${i===s.me?' (Bạn)':p.bot?' · AI':''}</b> · ${p.count} bài · ${p.kills.length}/3${p.protectDestroy||p.kills.includes('134')?' · 🛡 Không thể phá hủy':''}${p.protectSteal?' · Không thể cướp':''}${p.leaderRoll!==undefined?' · Chỉ số TL '+p.leaderRoll:''}${p.leaderRole?' · TL '+({'hero':'Anh hùng','monster':'Quái vật','challenge':'Thử thách'}[p.leaderRole]||''):''}<div class="party">${[p.leader,...p.party,...Object.values(p.items),...p.kills].filter(Boolean).map(id=>card(id,`detail('${id}','${i===s.me&&p.party.includes(id)?'hero':'view'}')`)).join('')}</div>${i!==s.me?'<span class="back"></span>'.repeat(Math.min(p.count,6)):''}</div>`).join(''));stableHTML('monsters',s.monsters.map(id=>card(id,`detail('${id}','monster')`)).join(''));stableHTML('hand',me.hand.map(id=>card(id,`detail('${id}','hand')`)).join(''));$('deck').textContent=s.deckCount;$('log').textContent=(s.combat?`${s.players[s.combat.actor].name} · ${s.combat.name} · ${s.combat.total} điểm · ${({win:'Tiêu diệt',counter:'Bị phản công',miss:'Không tiêu diệt (không phản công)'})[s.combat.outcome]} | `:'')+(s.log.at(-1)||'');showRoll(s);showEvent(s);$('draw').disabled=!myTurn||s.ap<1;$('reset').disabled=!myTurn||s.ap<3;$('next').disabled=!myTurn;$('effects').disabled=!myTurn;
let q=s.pending;stableHTML('reaction',s.phase==='done'?`<b>CHIẾN THẮNG: ${esc(s.players[s.winner].name)}</b>`:q?.type==='challenge'?q.responders[0]===s.me?`<button onclick="action('pass')">Bỏ qua</button> ${me.hand.includes('97')?'<button onclick="action(\'challenge\',{id:\'97\'})">Thử thách</button>':''} <button onclick="detail('${q.id}','view')">Xem bài đang đánh</button>`:`Đang chờ ${esc(s.players[q.responders[0]].name)} phản ứng ${card(q.id,`detail('${q.id}','view')`)}`:q?.type==='freeSkill'?q.actor===s.me?`<b>Kích hoạt kỹ năng miễn phí (0 điểm)</b> ${card(q.id,`detail('${q.id}','view')`)} <button class="gold" onclick="action('freeSkill')">Kích hoạt</button> <button onclick="action('skipSkill')">Bỏ qua</button>`:'Đang chờ chọn kỹ năng miễn phí':q?.type==='skillTarget'?q.actor===s.me?`<b>${({'auto:blindTake':'Chọn một lá úp từ tay đối thủ','auto:takeConditional':'Chọn đối thủ để lấy bài','auto:giveCard':'Chọn lá bài đưa cho đối thủ','auto:pickEnemyHero':'Chọn người chơi để xem anh hùng','auto:takeEnemyHero':'Chọn anh hùng từ tay đối thủ','auto:magicDestroy':'Chọn một lá bài để bỏ','auto:destroyOne':'Chọn anh hùng cần phá hủy','auto:attackCost':'Chọn bài trả chi phí tấn công','auto:costSacrifice':'Bỏ tối đa 3 lá: chọn lá cần bỏ hoặc kết thúc','auto:pickSacrifice':'Chọn người phải hy sinh một anh hùng','auto:costSteal':'Chọn lá cần bỏ để cướp anh hùng','auto:costTakeAll':'Chọn lá cần bỏ','auto:discard':'Chọn lá cần bỏ','auto:discardQueue':'Chọn lá cần bỏ','auto:sacrificeQueue':'Chọn anh hùng của bạn để hy sinh','auto:forceSacrifice':'Chọn người phải hy sinh anh hùng','auto:forceDiscard':'Chọn người phải bỏ bài','auto:returnAllItems':'Chọn người trả tất cả trang bị','auto:returnItemDraw':'Chọn anh hùng có trang bị cần trả','auto:swapHands':'Chọn người đổi bài trên tay','auto:swapLeaders':'Chọn người đổi thủ lĩnh',swapEnemy:'Trao đổi: chọn anh hùng đối thủ',swapOwn:'Trao đổi: chọn anh hùng của bạn',destroy:'Chọn anh hùng cần phá hủy'})[q.effect]||'Chọn mục tiêu kỹ năng:'}</b> <button class="gold" onclick="targetMenu()">Chọn bài / mục tiêu (${q.targets.length})</button> ${q.optional?`<button onclick="action('skipEffect')">${q.effect==='auto:viewOnly'?'Đã xem':q.effect==='auto:giveOrRefuse'?'Từ chối':q.effect==='auto:destroyOrSteal'?'Phá hủy thay vì cướp':'Bỏ qua / kết thúc'}</button>`:''}`:'Đang chọn mục tiêu kỹ năng':q?.type==='recover'?q.actor===s.me?`<span>Chọn lá lấy lại:</span>${q.ids.map(id=>card(id,`action('recover',{id:'${id}'})`)).join('')}`:'Đang chọn bài từ bài bỏ':q?.type==='counterChoice'?q.actor===s.me?`Quái vật phản công <button onclick="action('counterChoice',{draw:true})">Rút 2 lá</button> <button onclick="action('counterChoice',{draw:false})">Bỏ 2 lá</button>`:'Đang chọn hình phạt':q?.type==='modifierReact'?modifierPanel(s,q,me):q?.type==='druidReact'?q.responders[0]===s.me?`<b>Pháp Sư Thần Lộc: ${esc(s.players[q.actor].name)} đang có ${q.total} điểm</b> <button onclick="action('druidMinus')">-1 xúc xắc</button> <button onclick="action('druidPass')">Bỏ qua</button>`:'Đang chờ nội tại Pháp Sư Thần Lộc':q?.type==='rollBoost'?q.actor===s.me?`<b>Điều chỉnh xúc xắc: ${q.total} điểm</b> ${q.options.filter(o=>o.left>0).map(o=>`<button onclick="boostMenu('${o.key}')">Bỏ 1 lá: +${o.add} (${o.left} lần)</button>`).join(' ')} <button class="gold" onclick="action('rollPass')">Chốt điểm</button>`:'Đang điều chỉnh xúc xắc':q?.type==='attack'?q.actor===s.me?`Tấn công ${esc(q.name||q.id)}: ${q.total} điểm · Thắng ${q.win}${q.reverse?"−":"+"} <button onclick="action('resolve')">Chốt kết quả</button>`:'Đang xử lý tấn công':'');}
const cardName=c=>c.displayName||(!/^La[_ ]/i.test(c.name||'')?c.name:'')||({hero:'Anh hùng',leader:'Thủ lĩnh',monster:'Quái vật',item:'Vật phẩm',magic:'Phép thuật',challenge:'Thử thách',modifier:'Chuyển Đổi'}[c.type]+' #'+c.id);
function cardInfo(c){return `<div class="cardInfo">${esc(c.description||'Nội dung chữ chưa được nhập cho lá này.').replace(/\n/g,'<br>')}</div>`;}
function choose(id){modal(`<div class="detail"><img src="${C(id).src}"><section><h2>${esc(cardName(C(id)))}</h2>${cardInfo(C(id))}<button class="gold" onclick="closeM();action('leader',{id:'${id}'})">Chọn</button> <button onclick="closeM()">Đóng</button></section></div>`)}
function detail(id,where){let c=C(id),s=V,ok=s.phase==='play'&&s.me===s.turn&&!s.pending,buttons='';if(ok&&where==='hand'&&s.ap>=1&&!['challenge','modifier'].includes(c.type))buttons=`<button class="gold" onclick="play('${id}')">Sử dụng</button>`;if(ok&&where==='hero'&&s.ap>=1&&s.players[s.me].items[id]!=='58'&&(s.players[s.me].items[id]!=='63'||s.ap>=2)&&(!s.used.includes(id)||s.players[s.me].items[id]==='80'))buttons=`<button class="gold" onclick="closeM();action('skill',{id:'${id}'})">Kích hoạt</button>`;if(ok&&where==='monster'&&s.ap>=2)buttons=`<button class="gold" onclick="attack('${id}')">Tấn công</button>`;if(ok&&s.players[s.me].leader===id&&!s.players[s.me].leaderUsed&&((id==='163'&&s.ap>=2&&s.discard.length)||(id==='169'&&s.ap>=1)))buttons+=` <button class="gold" onclick="closeM();action('leaderSkill')">Dùng nội tại (${id==='163'?2:1}đ)</button>`;if(ok&&id==='139'&&s.players[s.me].kills.includes(id)&&!s.players[s.me].freeDrawUsed)buttons+=` <button class="gold" onclick="closeM();action('monsterSkill',{id:'139'})">Rút miễn phí</button>`;modal(`<div class="detail"><img src="${c.src}"><section><h2>${esc(cardName(c))}</h2><small>${esc(({hero:'Anh hùng',leader:'Thủ lĩnh',monster:'Quái vật',magic:'Phép thuật',item:'Trang bị',challenge:'Thử thách',modifier:'Chuyển Đổi xúc xắc'})[c.type]||'Lá bài')}</small>${cardInfo(c)}${buttons} <button onclick="closeM()">Đóng</button></section></div>`)}
function play(id){let c=C(id);if(id==='86'){let me=V.players[V.me],enemies=V.players.filter((p,i)=>i!==V.me&&p.party.length);if(me.hand.filter(h=>h!==id).length<1)return notice('Phép Hủy Diệt: cần 1 lá khác để bỏ');if(!enemies.length)return notice('Phép Hủy Diệt: đối thủ chưa có anh hùng');if(enemies.every(p=>p.protectDestroy||p.kills.includes('134')))return notice('Phép Hủy Diệt: anh hùng đối thủ đang được bảo vệ');}if(c.type==='item'){let cursed=+id>=57&&+id<=63;let targets=V.players.flatMap((p,i)=>(cursed?i!==V.me:i===V.me)?p.party.filter(h=>!p.items[h]).map(h=>[i,h]):[]);modal(`<h2>Chọn anh hùng nhận trang bị</h2>${targets.length?'':'<p>Chưa có anh hùng phù hợp.</p>'}<div class="shop">${targets.map(([i,h])=>card(h,`closeM();action('play',{id:'${id}',targetPlayer:${i},targetHero:'${h}'})`)).join('')}</div><button onclick="closeM()">Đóng</button>`)}else{closeM();action('play',{id}).then(ok=>{if(ok)notice(V.pending?.type==='challenge'?'Đã đánh bài — chờ phản ứng':V.log.at(-1)||'Đã sử dụng bài')})}}
function attack(id){modal(`<div class="detail"><img src="${C(id).src}"><section><h2>${esc(cardName(C(id)))}</h2>${cardInfo(C(id))}<p>Tốn 2 điểm hành động.</p><button class="gold" onclick="closeM();action('attack',{id:'${id}'})">Tấn công</button> <button onclick="closeM()">Đóng</button></section></div>`)}
function showLog(){modal('<h2>Nhật ký</h2>'+V.log.map(x=>`<p>${esc(x)}</p>`).join('')+'<button onclick="closeM()">Đóng</button>')}
function showDiscard(){modal('<h2>Bài bỏ</h2><div class="shop">'+V.discard.map(id=>card(id,`detail('${id}','view')`)).join('')+'</div><button onclick="closeM()">Đóng</button>')}
async function fullOnline(){try{if(document.fullscreenElement){await document.exitFullscreen();return}if(document.documentElement.requestFullscreen){await document.documentElement.requestFullscreen();try{await screen.orientation?.lock?.('landscape')}catch{}return}}catch{}notice('iPhone: thêm game vào màn hình chính và xoay ngang.')}

function showRoll(s){if(!s.dice.length){$('dice').textContent='—';$('rollResult').textContent='';return}let raw=s.dice.reduce((a,b)=>a+b,0),q=s.pending,adjusted=typeof q?.total==='number'?q.total:s.finalRoll?.seq===s.rollSeq?s.finalRoll.total:raw;$('rollResult').textContent='Xúc xắc: '+raw+' · Tổng: '+adjusted;if(lastRoll===s.rollSeq&&$('dice').querySelector('.cube'))return;lastRoll=s.rollSeq;$('dice').innerHTML=s.dice.map((d,i)=>`<span class="dieWrap"><span class="cube cube${i}">${[d,...[1,2,3,4,5,6].filter(x=>x!==d)].map((v,j)=>`<span class="face f${j}">${'⚀⚁⚂⚃⚄⚅'[v-1]}</span>`).join('')}</span></span>`).join('');$('dice').classList.remove('rolling');void $('dice').offsetWidth;$('dice').classList.add('rolling');}
function showEvent(s){let e=s.event;if(!e||lastEvent===e.seq)return;lastEvent=e.seq;let f=$('eventFx');f.innerHTML=`<div class="eventRing"></div><img class="eventCard" src="${C(e.id).src}" alt="">`;f.hidden=false;clearTimeout(fxTimer);fxTimer=setTimeout(()=>f.hidden=true,900);}

function boostMenu(key){let q=V.pending;if(q?.type!=='rollBoost'||q.actor!==V.me)return;modal(`<h2>Chọn một lá để bỏ</h2><div class="shop">${V.players[V.me].hand.map(id=>card(id,`closeM();action('rollBoost',{key:'${key}',id:'${id}'})`)).join('')}</div><button onclick="closeM()">Hủy</button>`);}

function modifierPanel(s,q,me){let title=`<b>${esc(s.players[q.actor].name)}: ${q.total} điểm — Chuyển Đổi</b> `;if(q.responders[0]!==s.me)return title+`Đang chờ ${esc(s.players[q.responders[0]].name)}`;if(q.recover)return title+' Chọn lá lấy lại: '+s.discard.map(id=>card(id,`action('modifierRecover',{id:'${id}'})`)).join('');return title+me.hand.filter(id=>C(id).type==='modifier'&&(!['184','185'].includes(C(id).modifierBase||id)||me.hand.length>1)).map(id=>card(id,`modifierMenu('${id}')`)).join('')+` <button onclick="action('modifierPass')">Bỏ qua</button>`;}
function modifierMenu(id){let q=V.pending,c=C(id),values=(c.modifierBase||id)==='188'&&q.kind==='attack'&&q.actor===V.me?[4]:c.values;if(q.actor===V.me&&V.players[V.me].leader==='166')values=[...new Set(values.flatMap(v=>[v,v+1,v-1]))];modal(`<div class="detail"><img src="${c.src}"><section><h2>${esc(cardName(c))}</h2>${cardInfo(c)}<p>Điểm hiện tại: ${q.total}</p>${values.map(v=>`<button onclick="modifierCost('${id}',${v})">${v>0?'+':''}${v}</button>`).join(' ')} <button onclick="closeM()">Hủy</button></section></div>`);}
function modifierCost(id,value){if(['184','185'].includes(C(id).modifierBase||id)){modal('<h2>Chọn thêm một lá để bỏ</h2>'+V.players[V.me].hand.filter(h=>h!==id).map(h=>card(h,`closeM();action('modifierPlay',{id:'${id}',value:${value},cost:'${h}'})`)).join('')+'<button onclick="closeM()">Hủy</button>');return;}if((C(id).modifierBase||id)==='191'){modal(`<h2>Bỏ toàn bộ bài còn lại để ${value>0?'+':''}${value}?</h2><button onclick="closeM();action('modifierPlay',{id:'${id}',value:${value}})">Xác nhận</button> <button onclick="closeM()">Hủy</button>`);return;}closeM();action('modifierPlay',{id,value});}

function targetMenu(){let q=V?.pending;if(q?.type!=='skillTarget'||q.actor!==V.me)return;modal(`<h2>${['auto:blindTake','auto:specialBlind'].includes(q.effect)?'Chọn một lá úp từ tay đối thủ':q.effect==='auto:viewOnly'?'Xem bài trên tay đối thủ':q.effect==='auto:visibleCard'?'Chọn lá bài muốn lấy':({'auto:magicDestroy':'Phép Hủy Diệt — chọn 1 lá để bỏ','auto:destroyOne':'Chọn anh hùng đối thủ để phá hủy','auto:freeCard':'Chọn bài sử dụng miễn phí','auto:freeEquip':'Chọn anh hùng nhận trang bị','auto:leaderRole':'Chọn vai trò thủ lĩnh','auto:leaderDrawCount':'Chọn số lá muốn rút','auto:chooseFive':'Chọn +5 hoặc -5','auto:topThree':'Chọn 1 lá trong 3 lá trên cùng','auto:topOrder':'Chọn lá đặt trên đầu bộ bài','auto:stealItemEquip':'Chọn anh hùng nhận vật phẩm','auto:drawExtra':'Nội tại: rút thêm 1 lá rồi bỏ 1 lá','auto:destroyOrSteal':'Nội tại: cướp thay vì phá hủy','auto:revealDraw':'Tiết lộ để rút thêm','auto:discardDraw':'Bỏ lá này để rút 2 lá','auto:endDraw':'Nội tại: rút 3 lá','auto:giveOrRefuse':'Đưa một lá hoặc từ chối','auto:freeAttack':'Chọn quái vật tấn công miễn phí'})[q.effect]||'Chọn bài / mục tiêu'}</h2><div class="targetGrid">${q.targets.map(t=>`<div><span>${esc(V.players[t.player].name)}</span>${q.effect==='auto:viewOnly'?card(t.id,`detail('${t.id}','view')`):targetCard(t)}</div>`).join('')}</div>${q.optional?`<button class="gold" onclick="closeM();action('skipEffect')">${q.effect==='auto:viewOnly'?'Đã xem':q.effect==='auto:giveOrRefuse'?'Từ chối':q.effect==='auto:destroyOrSteal'?'Phá hủy thay vì cướp':'Bỏ qua / kết thúc'}</button>`:''} <button onclick="closeM()">Đóng</button>`);}
